    u=auth(r)
    if not u:return err(401,'unauthorized')
    c=core.connect(); row=c.execute('SELECT * FROM files WHERE id=?',(int(r.match_info['id']),)).fetchone(); c.close()
    return js({'file':core.file_to_json(row)}) if row else err(404,'not found')

